pub use floatboard_core::{Result,store};
#[path="../src/database_repair.rs"]mod database_repair;
use std::fs;use serde_json::json;
#[test]fn oversized_and_invalid_payloads_are_omitted_and_evidence_is_exact(){let p=std::env::temp_dir().join(format!("floatboard-repair-limits-{}",uuid::Uuid::new_v4()));let root=p.join("data");let s=store::Store::open(&root,false).unwrap();s.db.execute("insert into tasks values('oversized',?1)",["x".repeat(1024*1024+1)]).unwrap();s.db.execute("insert into tasks values('mismatch',?1)",[json!({"id":"other","revision":1,"status":"running","plan":[],"blockers":[],"evidence":[]}).to_string()]).unwrap();s.db.execute_batch("pragma wal_checkpoint(TRUNCATE)").unwrap();drop(s);let original=fs::read(root.join("events.sqlite3")).unwrap();let r=database_repair::call(&root,"recover_copy",&json!({"confirmed":true})).unwrap();assert_eq!(r["status"],"no_readable_tasks");assert_eq!(r["recovery"]["rejected_rows"],2);assert_eq!(r["recovery"]["omitted_tasks"],2);assert_eq!(original,fs::read(root.join("events.sqlite3")).unwrap());let evidence=p.join(r["paths"]["evidence"].as_str().unwrap()).join("events.sqlite3");assert_eq!(original,fs::read(evidence).unwrap());assert!(r["paths"]["recovered_database"].is_null());fs::remove_dir_all(p).unwrap();}
